from AlgorithmImports import *


class PrivateLotStrategyAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)
        self.rsi_threshold = 70

        self.previous_closes = {}
        self.previous_spy_relation = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        if any(symbol not in data.bars for symbol in self.symbols):
            return

        bars = {symbol: data.bars[symbol] for symbol in self.symbols}

        previous_aapl_close = self.previous_closes.get(self.aapl)
        previous_spy_close = self.previous_closes.get(self.spy)

        self.spy_sma.update(self.time, bars[self.spy].close)
        self.aapl_rsi.update(self.time, bars[self.aapl].close)

        if previous_aapl_close is not None:
            if bars[self.aapl].close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Evaluate sells before buys.
        if self.strategy_a_shares > 0 and self.spy_sma.is_ready:
            spy_relation = bars[self.spy].close > self.spy_sma.current.value
            if self.previous_spy_relation is True and not spy_relation:
                self.market_order(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.is_ready:
            if self.aapl_rsi.current.value > self.rsi_threshold:
                self.market_order(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self.spy_sma.is_ready:
            spy_relation = bars[self.spy].close > self.spy_sma.current.value
            if self.previous_spy_relation is False and spy_relation:
                quantity = int((self.portfolio.total_portfolio_value * 0.40) / bars[self.spy].close)
                if quantity > 0:
                    self.market_order(self.spy, quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_rsi.is_ready:
            if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                quantity = int(20_000 / bars[self.aapl].close)
                if quantity > 0:
                    self.market_order(self.aapl, quantity)
                    self.strategy_b_shares = quantity

        if self.spy_sma.is_ready:
            self.previous_spy_relation = bars[self.spy].close > self.spy_sma.current.value

        for symbol in self.symbols:
            self.previous_closes[symbol] = bars[symbol].close
