from AlgorithmImports import *


class IndependentStrategySlots(QCAlgorithm):
    RSI_THRESHOLD = 70

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = [
            self.AddEquity("SPY", Resolution.Daily).Symbol,
            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_sma_values = RollingWindow[float](2)
        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        # Market-state values update continuously for every bar that is present.
        for symbol in self.symbols:
            if symbol not in data.Bars:
                continue

            bar = data.Bars[symbol]
            close = bar.Close

            if symbol == self.spy:
                self.spy_sma.Update(IndicatorDataPoint(bar.EndTime, close))
                if self.spy_sma.IsReady:
                    self.spy_sma_values.Add(self.spy_sma.Current.Value)

            if symbol == self.aapl:
                self.aapl_rsi.Update(IndicatorDataPoint(bar.EndTime, close))

                if symbol in self.previous_closes:
                    if close < self.previous_closes[symbol]:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

            self.previous_closes[symbol] = close

        # Skip all rule evaluation if any subscribed ticker lacks today's bar.
        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        # Do not trade until every indicator/window used by a rule is fully formed.
        if not self.spy_sma.IsReady or self.spy_sma_values.Count < 2:
            return

        if not self.aapl_rsi.IsReady or self.aapl not in self.previous_closes:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        yesterday_sma = self.spy_sma_values[1]
        today_sma = self.spy_sma_values[0]

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            if self.previous_closes[self.spy] <= yesterday_sma and spy_close < today_sma:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.Current.Value > self.RSI_THRESHOLD:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if self.previous_closes[self.spy] <= yesterday_sma and spy_close > today_sma:
                shares = int((0.40 * self.Portfolio.TotalPortfolioValue) // spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares == 0:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                shares = int(20_000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares
